<?php
declare(strict_types=1); require dirname(__DIR__,2).'/vendor/autoload.php';
use App\Bootstrap\App; use App\Database\Database; use App\Modules\Customers\CustomerRepository; use App\Modules\Shops\ShopRepository; use App\Support\Auth; use function App\Support\e;
new App();$db=Database::connection();$merchant=Auth::requireMerchant($db);$shopId=(int)$merchant['id'];$customers=(new CustomerRepository($db))->allForShop($shopId);$merchantShop=(new ShopRepository($db))->find($shopId);$merchantSection='customers';ob_start();
?><div class="merchant-shell"><?php require dirname(__DIR__,2).'/app/Views/components/merchant-sidebar.php'; ?><main class="merchant-main"><div class="merchant-topbar"><div><div class="small text-secondary">Relationships</div><h1 class="h3 fw-bold mb-0">Customers</h1></div></div><section class="panel"><div class="panel-heading"><div><h2 class="h5 fw-bold mb-1">Customer list</h2><p class="small text-secondary mb-0">Customers are created automatically when they place an order.</p></div><div class="small text-secondary"><?=number_format(count($customers))?> customer<?=count($customers)===1?'':'s'?></div></div><?php if(!$customers):?><div class="empty-state py-5"><div class="empty-state-icon">👥</div><h3 class="h5 fw-bold">No customers yet</h3><p class="text-secondary mb-0">Once customers place orders, their contact and order history will appear here.</p></div><?php else:?><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Customer</th><th>Phone</th><th>Orders</th><th>Total spent</th><th>Last order</th><th></th></tr></thead><tbody><?php foreach($customers as $c):?><tr><td><div class="fw-semibold"><?=e(trim(($c['first_name']??'').' '.($c['last_name']??''))?:'Customer')?></div><?php if($c['email']):?><div class="small text-secondary"><?=e($c['email'])?></div><?php endif;?></td><td><?=e($c['phone'])?></td><td><?=number_format((int)$c['total_orders'])?></td><td><?=e($merchantShop['currency']??'KES')?> <?=number_format((float)$c['total_spent'],2)?></td><td class="small text-secondary"><?=$c['last_order_at']?e(date('d M Y',strtotime($c['last_order_at']))):'—'?></td><td><a href="/customers/view?id=<?=(int)$c['id']?>" class="btn btn-sm btn-outline-dark">View</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></main></div><?php $content=ob_get_clean();$title='Customers';$merchantLayout=true;require dirname(__DIR__,2).'/app/Views/layouts/app.php';
